#![cfg(target_arch = "x86_64")]

/// Converted to Rust from the original C code generated by https://github.com/corsix/fast-crc32/
/// with the help of Claude.ai using:
///
/// ./generate -i avx512_vpclmulqdq -p crc32c -a v3x2
///
/// Modified as necessary for this Rust implementation.
///
/// Uses AVX-512 VPCLMULQDQ instructions
// Out of line: inlined into its entry point, the registers it saves are saved for the short
// buffers that return before reaching it
#[inline(never)]
#[target_feature(enable = "avx512vl,vpclmulqdq")]
pub unsafe fn crc32_iscsi_avx512_vpclmulqdq_v3x2(
    mut crc0: u32,
    mut buf: *const u8,
    mut len: usize,
) -> u32 {
    use crate::fusion::x86::*;

    // The head: to an 8-byte boundary a byte at a time, then to a 64-byte one a word at a time,
    // as far as the buffer goes. Its instructions are fixed, see `head`.
    (crc0, buf, len) = head(crc0, buf, len);

    if len >= 384 {
        // First vector chunk - load three 512-bit vectors (192 bytes total)
        let mut x0 = _mm512_loadu_si512(buf as *const __m512i);
        let mut x1 = _mm512_loadu_si512(buf.add(64) as *const __m512i);
        let mut x2 = _mm512_loadu_si512(buf.add(128) as *const __m512i);

        // Create the multiplication constant vector
        // Pattern: [0xa87ab8a8, 0, 0xab7aff2a, 0] repeated across all 128-bit lanes
        let k_128 = _mm_setr_epi32(0xa87ab8a8u32 as i32, 0, 0xab7aff2au32 as i32, 0);
        let mut k = _mm512_broadcast_i32x4(k_128);

        // XOR the CRC into the first vector's low 32 bits
        let crc_vec = _mm512_zextsi128_si512(_mm_cvtsi32_si128(crc0 as i32));
        x0 = _mm512_xor_si512(crc_vec, x0);

        // First round of polynomial multiplication
        let mut y0 = clmul_lo_avx512_vpclmulqdq(x0, k);
        x0 = clmul_hi_avx512_vpclmulqdq(x0, k);
        let mut y1 = clmul_lo_avx512_vpclmulqdq(x1, k);
        x1 = clmul_hi_avx512_vpclmulqdq(x1, k);
        let mut y2 = clmul_lo_avx512_vpclmulqdq(x2, k);
        x2 = clmul_hi_avx512_vpclmulqdq(x2, k);

        // XOR with next chunk of data using ternary logic (A XOR B XOR C)
        // 0x96 = A XOR B XOR C in ternary logic notation
        x0 = _mm512_ternarylogic_epi64(
            x0,
            y0,
            _mm512_loadu_si512(buf.add(192) as *const __m512i),
            0x96,
        );
        x1 = _mm512_ternarylogic_epi64(
            x1,
            y1,
            _mm512_loadu_si512(buf.add(256) as *const __m512i),
            0x96,
        );
        x2 = _mm512_ternarylogic_epi64(
            x2,
            y2,
            _mm512_loadu_si512(buf.add(320) as *const __m512i),
            0x96,
        );

        buf = buf.add(384);
        len -= 384;

        // Main loop - process 384 bytes at a time
        while len >= 384 {
            // First folding step
            y0 = clmul_lo_avx512_vpclmulqdq(x0, k);
            x0 = clmul_hi_avx512_vpclmulqdq(x0, k);
            y1 = clmul_lo_avx512_vpclmulqdq(x1, k);
            x1 = clmul_hi_avx512_vpclmulqdq(x1, k);
            y2 = clmul_lo_avx512_vpclmulqdq(x2, k);
            x2 = clmul_hi_avx512_vpclmulqdq(x2, k);

            x0 = _mm512_ternarylogic_epi64(x0, y0, _mm512_loadu_si512(buf as *const __m512i), 0x96);
            x1 = _mm512_ternarylogic_epi64(
                x1,
                y1,
                _mm512_loadu_si512(buf.add(64) as *const __m512i),
                0x96,
            );
            x2 = _mm512_ternarylogic_epi64(
                x2,
                y2,
                _mm512_loadu_si512(buf.add(128) as *const __m512i),
                0x96,
            );

            // Second folding step
            y0 = clmul_lo_avx512_vpclmulqdq(x0, k);
            x0 = clmul_hi_avx512_vpclmulqdq(x0, k);
            y1 = clmul_lo_avx512_vpclmulqdq(x1, k);
            x1 = clmul_hi_avx512_vpclmulqdq(x1, k);
            y2 = clmul_lo_avx512_vpclmulqdq(x2, k);
            x2 = clmul_hi_avx512_vpclmulqdq(x2, k);

            x0 = _mm512_ternarylogic_epi64(
                x0,
                y0,
                _mm512_loadu_si512(buf.add(192) as *const __m512i),
                0x96,
            );
            x1 = _mm512_ternarylogic_epi64(
                x1,
                y1,
                _mm512_loadu_si512(buf.add(256) as *const __m512i),
                0x96,
            );
            x2 = _mm512_ternarylogic_epi64(
                x2,
                y2,
                _mm512_loadu_si512(buf.add(320) as *const __m512i),
                0x96,
            );

            buf = buf.add(384);
            len -= 384;
        }

        // Reduce x0, x1, x2 to just x0
        let k_128 = _mm_setr_epi32(0x740eef02u32 as i32, 0, 0x9e4addf8u32 as i32, 0);
        k = _mm512_broadcast_i32x4(k_128);

        y0 = clmul_lo_avx512_vpclmulqdq(x0, k);
        x0 = clmul_hi_avx512_vpclmulqdq(x0, k);
        x0 = _mm512_ternarylogic_epi64(x0, y0, x1, 0x96);
        x1 = x2;

        y0 = clmul_lo_avx512_vpclmulqdq(x0, k);
        x0 = clmul_hi_avx512_vpclmulqdq(x0, k);
        x0 = _mm512_ternarylogic_epi64(x0, y0, x1, 0x96);

        // Fold each whole 64-byte block left into the one lane with the same 64-byte key the
        // reduction above used, rather than leaving it to the CRC32 instruction: a fold step
        // waits on one multiply, eight CRC32 instructions on each other. A 512-byte buffer
        // has two such blocks after the 384-byte step, a 1 KiB one four.
        while len >= 64 {
            y0 = clmul_lo_avx512_vpclmulqdq(x0, k);
            x0 = clmul_hi_avx512_vpclmulqdq(x0, k);
            x0 = _mm512_ternarylogic_epi64(x0, y0, _mm512_loadu_si512(buf as *const __m512i), 0x96);
            buf = buf.add(64);
            len -= 64;
        }

        // Reduce 512 bits to 128 bits
        // Multiple reduction constants for different parts of the 512-bit vector
        k = _mm512_setr_epi32(
            0x1c291d04u32 as i32,
            0,
            0xddc0152bu32 as i32,
            0, // Lane 0
            0x3da6d0cbu32 as i32,
            0,
            0xba4fc28eu32 as i32,
            0, // Lane 1
            0xf20c0dfeu32 as i32,
            0,
            0x493c7d27u32 as i32,
            0, // Lane 2
            0,
            0,
            0,
            0, // Lane 3 (unused)
        );

        y0 = clmul_lo_avx512_vpclmulqdq(x0, k);
        k = clmul_hi_avx512_vpclmulqdq(x0, k);
        y0 = _mm512_xor_si512(y0, k);

        // Extract 128-bit lanes and combine them
        let lane0 = _mm512_castsi512_si128(y0);
        let lane1 = _mm512_extracti32x4_epi32(y0, 1);
        let lane2 = _mm512_extracti32x4_epi32(y0, 2);
        let lane3 = _mm512_extracti32x4_epi32(x0, 3);

        // Combine all lanes using ternary logic
        let mut z0 = _mm_ternarylogic_epi64(lane0, lane1, lane2, 0x96);
        z0 = _mm_xor_si128(z0, lane3);

        // Reduce 128 bits to 32 bits using CRC32 instructions
        crc0 = _mm_crc32_u64(0, _mm_extract_epi64(z0, 0) as u64) as u32;
        crc0 = _mm_crc32_u64(crc0.into(), _mm_extract_epi64(z0, 1) as u64) as u32;
    }

    // The tail: what is left a word at a time, then a byte at a time. Its instructions are
    // fixed, see `tail`.
    tail(crc0, buf, len)
}

/// The kernel's head: CRC-32/ISCSI over the bytes from `buf` up to the first 64-byte boundary,
/// or as far towards it as `len` allows, returning the state and what is left. A buffer shorter
/// than 8 bytes is left whole for [`tail`].
///
/// Written as one block of inline assembly, so that its instructions, and the length checks
/// among them, are the same whatever compiler builds the crate and whoever calls the kernel:
/// built from intrinsics, its shape followed what the compiler could prove about the callers'
/// lengths, and grew by a third when the stream kernel became a caller. The intrinsics build
/// is kept for Miri, which runs no inline assembly.
///
/// # Safety
///
/// The CPU must have SSE4.2, and the `len` bytes from `buf` must be readable.
#[inline(always)]
unsafe fn head(crc: u32, buf: *const u8, len: usize) -> (u32, *const u8, usize) {
    #[cfg(not(miri))]
    {
        let mut crc = crc as u64;
        let (mut buf, mut len) = (buf, len);
        // SAFETY: every load is of bytes within the `len` from `buf`: nothing is read when fewer
        // than 8 are left; the byte loop stops at an 8-byte boundary, which is fewer than 8 bytes
        // on; the word loop runs only while at least 8 are left
        unsafe {
            core::arch::asm!(
                "cmp {n}, 8",
                "jb 5f",
                "test {p:l}, 7",
                "jz 3f",
                "2:",
                "crc32 {c:e}, byte ptr [{p}]",
                "add {p}, 1",
                "sub {n}, 1",
                "test {p:l}, 7",
                "jnz 2b",
                "3:",
                "test {p:l}, 56",
                "jz 5f",
                "cmp {n}, 8",
                "jb 5f",
                "crc32 {c}, qword ptr [{p}]",
                "add {p}, 8",
                "sub {n}, 8",
                "jmp 3b",
                "5:",
                c = inout(reg) crc,
                p = inout(reg) buf,
                n = inout(reg) len,
                options(pure, readonly, nostack),
            );
        }
        (crc as u32, buf, len)
    }

    #[cfg(miri)]
    {
        use crate::fusion::x86::*;

        let (mut crc, mut buf, mut len) = (crc, buf, len);
        if len >= 8 {
            while (buf as usize & 7) != 0 {
                crc = _mm_crc32_u8(crc, *buf);
                buf = buf.add(1);
                len -= 1;
            }
            while (buf as usize & 56) != 0 && len >= 8 {
                crc = _mm_crc32_u64(crc.into(), *(buf as *const u64)) as u32;
                buf = buf.add(8);
                len -= 8;
            }
        }
        (crc, buf, len)
    }
}

/// The kernel's tail: CRC-32/ISCSI over the `len` bytes from `buf`, a word at a time and then a
/// byte at a time. One block of inline assembly, as [`head`] is, with the intrinsics build kept
/// for Miri.
///
/// # Safety
///
/// The CPU must have SSE4.2, and the `len` bytes from `buf` must be readable.
#[inline(always)]
unsafe fn tail(crc: u32, buf: *const u8, len: usize) -> u32 {
    #[cfg(not(miri))]
    {
        let mut crc = crc as u64;
        // SAFETY: the word loop runs while at least 8 bytes are left, the byte loop while any are
        unsafe {
            core::arch::asm!(
                "cmp {n}, 8",
                "jb 3f",
                "2:",
                "crc32 {c}, qword ptr [{p}]",
                "add {p}, 8",
                "sub {n}, 8",
                "cmp {n}, 8",
                "jae 2b",
                "3:",
                "test {n}, {n}",
                "jz 5f",
                "4:",
                "crc32 {c:e}, byte ptr [{p}]",
                "add {p}, 1",
                "sub {n}, 1",
                "jnz 4b",
                "5:",
                c = inout(reg) crc,
                p = inout(reg) buf => _,
                n = inout(reg) len => _,
                options(pure, readonly, nostack),
            );
        }
        crc as u32
    }

    #[cfg(miri)]
    {
        use crate::fusion::x86::*;

        let (mut crc, mut buf, mut len) = (crc, buf, len);
        while len >= 8 {
            crc = _mm_crc32_u64(crc.into(), *(buf as *const u64)) as u32;
            buf = buf.add(8);
            len -= 8;
        }
        while len > 0 {
            crc = _mm_crc32_u8(crc, *buf);
            buf = buf.add(1);
            len -= 1;
        }
        crc
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::crc32::consts::CRC32_ISCSI;

    /// The kernel, called directly, against the software path, the oracle: every length through
    /// three of its 384-byte steps, which takes in the short buffers the stream kernel hands it
    /// and the head's early return below 8 bytes, from every start within a cache line's first
    /// 16 bytes and a few later ones, from the init state, zero and a carried state.
    #[test]
    #[cfg_attr(miri, ignore)]
    fn matches_software() {
        if !(is_x86_feature_detected!("avx512vl")
            && is_x86_feature_detected!("vpclmulqdq")
            && is_x86_feature_detected!("sse4.2"))
        {
            eprintln!("skipping matches_software: no AVX-512 VPCLMULQDQ");
            return;
        }

        let data: Vec<u8> = (0..1400u32)
            .map(|i| (i.wrapping_mul(2654435761) >> 13) as u8)
            .collect();
        // The kernel's own data, from a 64-byte boundary, so that the offsets below are the
        // offsets of the head within a cache line
        let base = data.as_ptr().align_offset(64);

        for offset in (0..16).chain([31, 56, 63]) {
            for len in 0..=3 * 384 + 72 {
                let bytes = &data[base + offset..base + offset + len];
                for state in [0xffff_ffffu32, 0, 0x1234_5678] {
                    let expected =
                        crate::arch::software::update(state as u64, bytes, &CRC32_ISCSI) as u32;
                    // SAFETY: the features were detected above
                    let got = unsafe {
                        crc32_iscsi_avx512_vpclmulqdq_v3x2(state, bytes.as_ptr(), bytes.len())
                    };
                    assert_eq!(
                        got, expected,
                        "offset {offset}, length {len}, state {state:#x}"
                    );
                }
            }
        }
    }
}
